"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type RefObject,
} from "react";
import { motion, useReducedMotion } from "motion/react";
import {
  ArrowDown,
  ArrowUp,
  FileSearch,
  GitPullRequest,
  ListChecks,
  Square,
} from "lucide-react";

const cx = (...c: (string | false | null | undefined)[]) =>
  c.filter(Boolean).join(" ");

type Message = {
  id: string;
  role: "user" | "assistant";
  text: string;
};

const CATCH_UP_MS = 180;
const FLOOR_CPS = 45;

function lastWordBoundary(source: string, cut: number) {
  if (cut >= source.length) return source.length;
  const i = source.lastIndexOf(" ", cut);
  return i === -1 ? 0 : i;
}

function useSmoothedText() {
  const [text, setText] = useState("");
  const [done, setDone] = useState(false);
  const targetRef = useRef("");
  const shownRef = useRef(0);
  const endedRef = useRef(false);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    let raf = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const dt = Math.min(now - last, 64);
      last = now;
      const target = targetRef.current;
      const behind = target.length - shownRef.current;
      if (behind > 0) {
        shownRef.current = reduceMotion
          ? target.length
          : Math.min(
              target.length,
              shownRef.current +
                behind * (1 - Math.exp(-dt / CATCH_UP_MS)) +
                (FLOOR_CPS * dt) / 1000,
            );
        const cut = Math.floor(shownRef.current);
        const finished = endedRef.current && cut >= target.length;
        const safe = finished ? target.length : lastWordBoundary(target, cut);
        setText(target.slice(0, safe));
        if (finished) setDone(true);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [reduceMotion]);

  const push = useCallback((chunk: string) => {
    targetRef.current += chunk;
  }, []);
  const end = useCallback(() => {
    endedRef.current = true;
  }, []);
  const reset = useCallback(() => {
    targetRef.current = "";
    shownRef.current = 0;
    endedRef.current = false;
    setText("");
    setDone(false);
  }, []);
  return { text, done, push, end, reset };
}

function StreamingWords({ text }: { text: string }) {
  const reduced = useReducedMotion();
  if (reduced) return <>{text}</>;
  const words = text.match(/\S+\s*/g) ?? [];
  return (
    <>
      {words.map((word, i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0, filter: "blur(4px)" }}
          animate={{ opacity: 1, filter: "blur(0px)" }}
          transition={{ duration: 0.24, ease: [0.23, 1, 0.32, 1] }}
          className="inline-block whitespace-pre-wrap"
        >
          {word}
        </motion.span>
      ))}
    </>
  );
}

function useScrollFade<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [edges, setEdges] = useState({ start: false, end: false });

  const update = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    const { scrollTop, scrollHeight, clientHeight } = el;
    setEdges({
      start: scrollTop > 1,
      end: Math.ceil(scrollTop + clientHeight) < scrollHeight - 1,
    });
  }, []);

  useEffect(() => {
    update();
    const el = ref.current;
    const view = el?.ownerDocument.defaultView;
    if (!el || !view?.ResizeObserver) return;
    const observer = new view.ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, [update]);

  return { ref, edges, onScroll: update };
}

function useStickToBottom(scrollRef: RefObject<HTMLDivElement | null>) {
  const stickRef = useRef(true);
  const [showJump, setShowJump] = useState(false);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;

    const sync = () => {
      const overflowing = el.scrollHeight - el.clientHeight > 1;
      const distance = el.scrollHeight - el.scrollTop - el.clientHeight;
      const atBottom = !overflowing || distance < 24;
      stickRef.current = atBottom;
      setShowJump(overflowing && !atBottom);
    };

    const onIntent = (e: WheelEvent | TouchEvent) => {
      const up = "deltaY" in e ? e.deltaY < 0 : true;
      if (!up) return;
      if (el.scrollHeight - el.clientHeight > 1 && el.scrollTop > 0) {
        stickRef.current = false;
      }
    };

    const observer = new ResizeObserver(() => {
      if (stickRef.current) el.scrollTop = el.scrollHeight;
      sync();
    });
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);

    el.addEventListener("wheel", onIntent, { passive: true });
    el.addEventListener("touchmove", onIntent, { passive: true });
    el.addEventListener("scroll", sync, { passive: true });

    el.scrollTop = el.scrollHeight;
    sync();
    return () => {
      observer.disconnect();
      el.removeEventListener("wheel", onIntent);
      el.removeEventListener("touchmove", onIntent);
      el.removeEventListener("scroll", sync);
    };
  }, []);

  const jumpToLatest = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    stickRef.current = true;
    setShowJump(false);
    el.scrollTop = el.scrollHeight;
  }, []);

  return { showJump, jumpToLatest };
}

const SUGGESTIONS = [
  { icon: FileSearch, label: "Summarize the latest release notes" },
  { icon: GitPullRequest, label: "What changed in this pull request?" },
  { icon: ListChecks, label: "Draft acceptance criteria for the new filter" },
];

const CANNED_REPLY =
  "The latest release centered on the new filter panel, faster search " +
  "indexing, and a set of smaller fixes for keyboard navigation. I can pull " +
  "the full changelog, or turn any part of it into acceptance criteria: just " +
  "tell me which area to focus on.";

const LIVE_ID = "a-seed";

const SEED_MESSAGES: Message[] = [
  { id: "u-1", role: "user", text: "Summarize the latest release notes" },
  {
    id: "a-1",
    role: "assistant",
    text: "Version 2.4 focused on the new filter panel, faster search indexing, and keyboard-navigation fixes.",
  },
  { id: "u-2", role: "user", text: "What changed in the filter panel?" },
  {
    id: "a-2",
    role: "assistant",
    text: "It moved into a docked sidebar, gained saved views, and now remembers your last query per project.",
  },
  {
    id: "u-3",
    role: "user",
    text: "Draft acceptance criteria for the new filter",
  },
  {
    id: LIVE_ID,
    role: "assistant",
    text: "Filters apply instantly, saved views persist per project, and every control stays reachable by keyboard.",
  },
];

export default function AiChat3() {
  const reduced = useReducedMotion();
  const [messages, setMessages] = useState<Message[]>(SEED_MESSAGES);
  const [liveId, setLiveId] = useState<string | null>(null);
  const [stopped, setStopped] = useState(false);
  const [value, setValue] = useState("");
  const [runId, setRunId] = useState(0);

  const { text: streamText, done, push, end, reset } = useSmoothedText();
  const transcript = useScrollFade<HTMLDivElement>();
  const { showJump, jumpToLatest } = useStickToBottom(transcript.ref);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const transportRef = useRef<number | null>(null);

  const streaming = liveId !== null && !done && !stopped;
  const pending = streaming && streamText === "";

  useEffect(() => {
    if (!liveId) return;
    if (reduced) {
      push(CANNED_REPLY);
      end();
      return;
    }
    const chunks = CANNED_REPLY.match(/\S+\s*/g) ?? [];
    let i = 0;
    transportRef.current = window.setInterval(() => {
      const n = 1 + Math.floor(Math.random() * 3);
      push(chunks.slice(i, i + n).join(""));
      i += n;
      if (i >= chunks.length) {
        end();
        if (transportRef.current) window.clearInterval(transportRef.current);
        transportRef.current = null;
      }
    }, 130);
    return () => {
      if (transportRef.current) window.clearInterval(transportRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [liveId, runId, reduced]);

  const autosize = () => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  };

  const handleSend = useCallback(
    (text: string) => {
      const t = text.trim();
      if (!t) return;
      const uid = `u-${Date.now()}`;
      const aid = `a-${Date.now()}`;
      reset();
      setStopped(false);
      setMessages((m) => [
        ...m,
        { id: uid, role: "user", text: t },
        { id: aid, role: "assistant", text: CANNED_REPLY },
      ]);
      setLiveId(aid);
      setRunId((n) => n + 1);
      setValue("");
    },
    [reset],
  );

  const handleStop = useCallback(() => {
    if (transportRef.current) {
      window.clearInterval(transportRef.current);
      transportRef.current = null;
    }
    end();
    setStopped(true);
  }, [end]);

  const empty = messages.length === 0;

  return (
    <div className="relative flex h-full min-h-[560px] w-full flex-col overflow-hidden bg-white p-4 sm:p-6 dark:bg-neutral-950">
      <div className="mx-auto flex w-full max-w-sm flex-1 flex-col space-y-1 rounded-[var(--rb-r-3xl,16px)] border border-neutral-200/70 bg-neutral-50 p-1 dark:border-neutral-800 dark:bg-neutral-900">
        <div className="flex h-12 shrink-0 items-center rounded-[var(--rb-r-xl,12px)] border border-neutral-200/70 bg-white px-4 dark:border-neutral-800 dark:bg-neutral-950">
          <span className="text-[13px] font-medium text-neutral-900 dark:text-neutral-100">
            Assistant
          </span>
          <span className="ml-auto inline-flex items-center gap-1.5 text-xs text-neutral-500">
            <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-neutral-300 dark:bg-neutral-600" />
            Ready
          </span>
        </div>

        <div className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-[var(--rb-r-xl,12px)] border border-neutral-200/70 bg-white dark:border-neutral-800 dark:bg-neutral-950">
          <div className="relative flex min-h-0 flex-1 flex-col">
            <div
              ref={transcript.ref}
              onScroll={transcript.onScroll}
              className="min-h-0 flex-1 overflow-y-auto overscroll-contain [overflow-anchor:none]"
            >
              <div className="flex min-h-full flex-col px-4 py-4">
                {empty ? (
                  <div className="m-auto w-full">
                    <div className="space-y-1.5">
                      <h2 className="text-base font-medium tracking-[-0.01em] text-neutral-900 dark:text-neutral-100">
                        How can I help?
                      </h2>
                      <p className="text-[13px] leading-relaxed text-neutral-500">
                        Ask about the repository, or start from an example.
                      </p>
                    </div>
                    <div className="mt-5 space-y-1">
                      {SUGGESTIONS.map(({ icon: Icon, label }) => (
                        <button
                          key={label}
                          type="button"
                          onClick={() => handleSend(label)}
                          className="cursor-pointer flex w-full items-center gap-2.5 rounded-[var(--rb-r-md,8px)] bg-neutral-100 px-2.5 py-2 text-left transition-[transform,background-color] duration-100 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-neutral-200 active:scale-[0.99] focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-[var(--rb-accent,oklch(20.5%_0_0))] dark:bg-neutral-800 dark:hover:bg-neutral-700 dark:focus-visible:outline-[var(--rb-accent,oklch(100%_0_0))]"
                        >
                          <Icon className="h-4 w-4 shrink-0 text-neutral-500" />
                          <span className="min-w-0 truncate text-[13px] text-neutral-700 dark:text-neutral-300">
                            {label}
                          </span>
                        </button>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col gap-4">
                    {messages.map((message) => {
                      if (message.role === "user") {
                        return (
                          <div key={message.id} className="flex">
                            <div className="ml-auto max-w-[85%] rounded-[var(--rb-r-2xl,14px)] bg-neutral-100 px-3 py-2 text-[13px] leading-5 text-neutral-900 dark:bg-neutral-800 dark:text-neutral-100">
                              {message.text}
                            </div>
                          </div>
                        );
                      }
                      const isLive = message.id === liveId;
                      const showSkeleton = isLive && pending;
                      return (
                        <div key={message.id} className="min-h-[1.25rem]">
                          {showSkeleton ? (
                            <div className="flex h-5 items-center gap-1.5 text-xs text-neutral-400">
                              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-neutral-400 motion-reduce:animate-none dark:bg-neutral-500" />
                              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-neutral-400 motion-reduce:animate-none dark:bg-neutral-500 [animation-delay:150ms]" />
                              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-neutral-400 motion-reduce:animate-none dark:bg-neutral-500 [animation-delay:300ms]" />
                            </div>
                          ) : (
                            <p className="text-[13px] leading-relaxed text-neutral-900 dark:text-neutral-100">
                              {isLive && streaming ? (
                                <StreamingWords text={streamText} />
                              ) : (
                                message.text
                              )}
                            </p>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            <div
              aria-hidden="true"
              className={cx(
                "pointer-events-none absolute inset-x-0 top-0 h-8 bg-gradient-to-b from-white to-transparent transition-opacity duration-200 ease-out dark:from-neutral-950",
                transcript.edges.start ? "opacity-100" : "opacity-0",
              )}
            />
            <div
              aria-hidden="true"
              className={cx(
                "pointer-events-none absolute inset-x-0 bottom-0 h-8 bg-gradient-to-t from-white to-transparent transition-opacity duration-200 ease-out dark:from-neutral-950",
                transcript.edges.end ? "opacity-100" : "opacity-0",
              )}
            />

            {showJump && (
              <motion.button
                type="button"
                onClick={jumpToLatest}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.15 }}
                className="cursor-pointer absolute bottom-3 left-1/2 z-10 inline-flex h-8 -translate-x-1/2 items-center gap-1.5 rounded-[var(--rb-r-md,8px)] border border-neutral-200/70 bg-white px-3 text-[13px] font-medium text-neutral-700 shadow-[0_4px_16px_-4px_rgba(0,0,0,0.10)] transition-colors hover:bg-neutral-50 focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--rb-accent,oklch(20.5%_0_0))] dark:border-neutral-800 dark:bg-neutral-800 dark:text-neutral-200 dark:shadow-none dark:hover:bg-neutral-700 dark:focus-visible:outline-[var(--rb-accent,oklch(100%_0_0))]"
              >
                <ArrowDown className="h-3.5 w-3.5 shrink-0" />
                Jump to latest
              </motion.button>
            )}
          </div>

          <div className="shrink-0 p-3">
            <div className="flex items-end gap-1.5 rounded-[var(--rb-r-2xl,14px)] border border-neutral-200 bg-white p-1.5 transition-colors focus-within:border-neutral-300 dark:border-neutral-800 dark:bg-neutral-900 dark:focus-within:border-neutral-700">
              <textarea
                ref={textareaRef}
                rows={1}
                value={value}
                onChange={(e) => {
                  setValue(e.target.value);
                  autosize();
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    handleSend(value);
                  }
                }}
                placeholder="Ask anything"
                className="block max-h-40 min-w-0 flex-1 resize-none bg-transparent px-1.5 py-1 text-[13px] leading-5 text-neutral-900 outline-none placeholder:text-neutral-500 dark:text-neutral-100"
              />
              {streaming ? (
                <button
                  type="button"
                  onClick={handleStop}
                  key="stop"
                  aria-label="Stop generating"
                  className="cursor-pointer inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-[var(--rb-r-md,8px)] bg-[var(--rb-accent,oklch(20.5%_0_0))] text-[var(--rb-accent-fg,oklch(100%_0_0))] transition-[transform,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-[color-mix(in_oklab,var(--rb-accent,oklch(20.5%_0_0))_90%,transparent)] active:scale-95 focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--rb-accent,oklch(20.5%_0_0))] dark:bg-[var(--rb-accent,oklch(100%_0_0))] dark:text-[var(--rb-accent-fg,oklch(20.5%_0_0))] dark:focus-visible:outline-[var(--rb-accent,oklch(100%_0_0))]"
                >
                  <Square className="h-3.5 w-3.5 shrink-0" />
                </button>
              ) : (
                <button
                  type="button"
                  onClick={() => handleSend(value)}
                  key="send"
                  aria-label="Send"
                  disabled={value.trim().length === 0}
                  className="cursor-pointer inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-[var(--rb-r-md,8px)] bg-[var(--rb-accent,oklch(20.5%_0_0))] text-[var(--rb-accent-fg,oklch(100%_0_0))] transition-[transform,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-[color-mix(in_oklab,var(--rb-accent,oklch(20.5%_0_0))_90%,transparent)] active:scale-95 focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--rb-accent,oklch(20.5%_0_0))] disabled:bg-neutral-200 disabled:text-neutral-400 dark:bg-[var(--rb-accent,oklch(100%_0_0))] dark:text-[var(--rb-accent-fg,oklch(20.5%_0_0))] dark:focus-visible:outline-[var(--rb-accent,oklch(100%_0_0))] dark:disabled:bg-neutral-700"
                >
                  <ArrowUp className="h-4 w-4 shrink-0" />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
